-- Generated by scripts/places (OHSAA PDFs). Inserts MeetPlacings (Place, 0 points, no participant) only where the performance has none. Id-independent; re-runnable.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @pid INT;

-- 1960 Class A State Championships: Bill Heffelfinger 200M place 1
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE a.FirstName+N' '+a.LastName=N'Bill Heffelfinger' AND a.Gender=1 AND m.Name=N'1960 Class A State Championships' AND CAST(m.Date AS date)='1960-06-01' AND e.Name=N'200M' AND e.Gender=1);
IF @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) SELECT MeetId, Id, NULL, 1, 0, 0 FROM Performances WHERE Id=@pid;
